:root {
  --bg: #1e1e2e;
  --card-bg: #2a2a3c;
  --text: #e0e0f0;
  --accent: #7aa2f7;
  --accent-hover: #9bb8ff;
  --danger: #f7768e;
  --border: #3b3b52;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  padding: 16px;
}

.card {
  width: 100%;
  max-width: 480px;
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

header {
  margin-bottom: 20px;
}

h1 {
  margin: 0 0 4px;
  font-size: 1.5rem;
  font-weight: 700;
}

.subtitle {
  margin: 0;
  font-size: 0.9rem;
  opacity: 0.7;
}

.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 4px;
}

input[type="number"] {
  flex: 1;
  min-width: 0;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: inherit;
  color: var(--text);
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  outline: none;
  transition: border-color 0.15s;
}

input[type="number"]:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px rgba(122, 162, 247, 0.3);
}

input[type="number"]::placeholder {
  color: var(--text);
  opacity: 0.4;
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 10px 18px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
}

button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.97);
}

#add-btn {
  background: var(--accent);
  color: #1e1e2e;
}

#add-btn:hover {
  background: var(--accent-hover);
}

.clear-btn {
  background: transparent;
  color: var(--danger);
  border: 1px solid var(--danger);
  padding: 6px 12px;
  font-size: 0.85rem;
}

.clear-btn:hover {
  background: var(--danger);
  color: #1e1e2e;
}

.hint {
  margin: 0 0 20px;
  font-size: 0.8rem;
  opacity: 0.5;
}

.stats {
  margin-bottom: 20px;
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.stat {
  background: var(--bg);
  border-radius: 8px;
  padding: 12px 8px;
  text-align: center;
}

.stat-label {
  display: block;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  opacity: 0.6;
  margin-bottom: 4px;
}

.stat-value {
  display: block;
  font-size: 1.15rem;
  font-weight: 700;
  word-break: break-word;
}

.readings-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

.readings-header h2 {
  margin: 0;
  font-size: 1.1rem;
}

.readings-list {
  list-style: none;
  margin: 0;
  padding: 0;
  max-height: 220px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.readings-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  background: var(--bg);
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 0.95rem;
  word-break: break-word;
}

.readings-list li.empty-state {
  justify-content: center;
  opacity: 0.5;
  font-style: italic;
}

.delete-btn {
  background: transparent;
  color: var(--text);
  opacity: 0.5;
  padding: 2px 6px;
  font-size: 1rem;
  line-height: 1;
  border-radius: 4px;
}

.delete-btn:hover {
  opacity: 1;
  color: var(--danger);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .input-row {
    flex-direction: column;
  }
  #add-btn {
    width: 100%;
  }
}

(function () {
  'use strict';

  var readings = [];

  var form = document.getElementById('reading-form');
  var input = document.getElementById('temp-input');
  var list = document.getElementById('readings-list');
  var clearBtn = document.getElementById('clear-btn');
  var statMin = document.getElementById('stat-min');
  var statMax = document.getElementById('stat-max');
  var statAvg = document.getElementById('stat-avg');

  function format(value) {
    return Number.isInteger(value) ? String(value) : value.toFixed(1);
  }

  function renderStats() {
    if (readings.length === 0) {
      statMin.textContent = '\u2014';
      statMax.textContent = '\u2014';
      statAvg.textContent = '\u2014';
      return;
    }
    var min = Math.min.apply(null, readings);
    var max = Math.max.apply(null, readings);
    var avg = readings.reduce(function (a, b) { return a + b; }, 0) / readings.length;
    statMin.textContent = format(min) + '\u00B0C';
    statMax.textContent = format(max) + '\u00B0C';
    statAvg.textContent = format(avg) + '\u00B0C';
  }

  function renderList() {
    list.innerHTML = '';
    if (readings.length === 0) {
      var empty = document.createElement('li');
      empty.className = 'empty-state';
      empty.textContent = 'No readings yet.';
      list.appendChild(empty);
      return;
    }
    readings.forEach(function (value, index) {
      var li = document.createElement('li');
      var span = document.createElement('span');
      span.textContent = format(value) + '\u00B0C';
      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'delete-btn';
      del.textContent = '\u00D7';
      del.setAttribute('aria-label', 'Remove reading ' + format(value) + ' degrees Celsius');
      del.addEventListener('click', function () {
        readings.splice(index, 1);
        render();
      });
      li.appendChild(span);
      li.appendChild(del);
      list.appendChild(li);
    });
  }

  function render() {
    renderList();
    renderStats();
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var raw = input.value.trim();
    if (raw === '') {
      return;
    }
    var value = Number(raw);
    if (!isFinite(value)) {
      input.value = '';
      return;
    }
    readings.push(value);
    input.value = '';
    input.focus();
    render();
  });

  clearBtn.addEventListener('click', function () {
    readings = [];
    render();
    input.focus();
  });

  render();
})();
